begin;
set local search_path=public,extensions;
select plan(18);
select has_function('public','get_owner_appointment_overview',array['uuid','timestamp with time zone'],'overview RPC exists');
select has_function('public','list_owner_appointments',array['uuid','text','text','uuid','uuid','date','date','text','text','integer','integer'],'list RPC exists');
select has_function('public','get_owner_appointment_detail',array['uuid','uuid'],'detail RPC exists');
select ok((select relrowsecurity from pg_class where oid='public.appointments'::regclass),'appointment RLS remains enabled');
select ok(has_table_privilege('anon','public.appointments','select')=false,'anonymous has no appointment table read');
select ok(has_function_privilege('anon','public.list_owner_appointments(uuid,text,text,uuid,uuid,date,date,text,text,integer,integer)','execute')=false,'anonymous cannot execute owner list');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000101","role":"authenticated"}',true);
select is((public.list_owner_appointments('10000000-0000-4000-8000-000000000001','','all',null,null,null,null,'start','asc',10,0)->>'total')::integer,1,'owner reads own organization appointments');
select is(public.get_owner_appointment_detail('10000000-0000-4000-8000-000000000001','19000000-0000-4000-8000-000000000101')->>'reference','SF-FICTIONAL-EXISTING','owner reads same-tenant detail');
select is(public.get_owner_appointment_detail('10000000-0000-4000-8000-000000000001','29000000-0000-4000-8000-000000000201'),null,'unknown detail fails without disclosure');
select is((public.list_owner_appointments('10000000-0000-4000-8000-000000000001','Casey','confirmed',null,null,'2026-09-07','2026-09-07','start','asc',5,0)->>'total')::integer,1,'search status and local date filters compose');
select is((public.get_owner_appointment_overview('10000000-0000-4000-8000-000000000001','2026-09-06 21:30:00+00')->>'today')::integer,1,'overview uses organization-local midnight');
select is(jsonb_array_length(public.get_owner_appointment_detail('10000000-0000-4000-8000-000000000001','19000000-0000-4000-8000-000000000101')->'events'),0,'event projection is tenant bounded');
select ok(not (public.get_owner_appointment_detail('10000000-0000-4000-8000-000000000001','19000000-0000-4000-8000-000000000101')::text ~ 'token_hash|recipient_email|metadata'),'detail omits secrets and private event metadata');
select throws_ok($$select public.list_owner_appointments('20000000-0000-4000-8000-000000000001','','all',null,null,null,null,'start','asc',10,0)$$,'42501','organization not found','cross-tenant list fails closed');
select throws_ok($$select public.list_owner_appointments('10000000-0000-4000-8000-000000000001','','all',null,null,null,null,'unsafe','asc',10,0)$$,'22023','invalid appointment query','sort allowlist enforced');
select throws_ok($$select public.list_owner_appointments('10000000-0000-4000-8000-000000000001','','all',null,null,null,null,'start','asc',100,0)$$,'22023','invalid list window','pagination is bounded');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000102","role":"authenticated"}',true);
select throws_ok($$select public.get_owner_appointment_overview('10000000-0000-4000-8000-000000000001')$$,'42501','organization not found','staff cannot execute owner overview');
reset role;set local role anon;
select throws_ok($$select public.get_owner_appointment_detail('10000000-0000-4000-8000-000000000001','19000000-0000-4000-8000-000000000101')$$,'42501',null,'anonymous cannot execute owner detail');
select * from finish();rollback;
